// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// SuggestAddresses Подсказки адреса (прокси к Dadata, только до дома)
	// (GET /api/v1/addresses)
	SuggestAddresses(ctx context.Context, request SuggestAddressesRequestObject) (SuggestAddressesResponseObject, error)
	// AdminListEvents События домов УК диспетчера
	// (GET /api/v1/admin/events)
	AdminListEvents(ctx context.Context, request AdminListEventsRequestObject) (AdminListEventsResponseObject, error)
	// AdminCreateEvent Создать плановое событие (пуш жильцам дома)
	// (POST /api/v1/admin/events)
	AdminCreateEvent(ctx context.Context, request AdminCreateEventRequestObject) (AdminCreateEventResponseObject, error)
	// AdminRescheduleEvent Сдвинуть сроки (пуш жильцам)
	// (PATCH /api/v1/admin/events/{id})
	AdminRescheduleEvent(ctx context.Context, request AdminRescheduleEventRequestObject) (AdminRescheduleEventResponseObject, error)
	// AdminResolveEventEscalation Решение инженера по спорному событию
	// (POST /api/v1/admin/events/{id}/escalation-resolve)
	AdminResolveEventEscalation(ctx context.Context, request AdminResolveEventEscalationRequestObject) (AdminResolveEventEscalationResponseObject, error)
	// AdminSetEventStatus «Готово» → ждёт подтверждения жильцов
	// (PATCH /api/v1/admin/events/{id}/status)
	AdminSetEventStatus(ctx context.Context, request AdminSetEventStatusRequestObject) (AdminSetEventStatusResponseObject, error)
	// AdminListIncidents Заявки домов УК диспетчера, по убыванию подписчиков
	// (GET /api/v1/admin/incidents)
	AdminListIncidents(ctx context.Context, request AdminListIncidentsRequestObject) (AdminListIncidentsResponseObject, error)
	// AdminResolveIncidentEscalation Решение инженера по спорной заявке
	// (POST /api/v1/admin/incidents/{id}/escalation-resolve)
	AdminResolveIncidentEscalation(ctx context.Context, request AdminResolveIncidentEscalationRequestObject) (AdminResolveIncidentEscalationResponseObject, error)
	// AdminSetIncidentStatus Новая → В работе → Выполнено (запускает рукопожатие)
	// (PATCH /api/v1/admin/incidents/{id}/status)
	AdminSetIncidentStatus(ctx context.Context, request AdminSetIncidentStatusRequestObject) (AdminSetIncidentStatusResponseObject, error)
	// MaxWebhook Входящие обновления от MAX Bot API (callback-кнопки)
	// (POST /api/v1/bot/webhook)
	MaxWebhook(ctx context.Context, request MaxWebhookRequestObject) (MaxWebhookResponseObject, error)
	// ListEvents Незакрытые события дома текущего пользователя
	// (GET /api/v1/events)
	ListEvents(ctx context.Context, request ListEventsRequestObject) (ListEventsResponseObject, error)
	// ConfirmEvent Подтверждение результата события жильцом
	// (POST /api/v1/events/{id}/confirmation)
	ConfirmEvent(ctx context.Context, request ConfirmEventRequestObject) (ConfirmEventResponseObject, error)
	// ListIncidents Незакрытые заявки дома текущего пользователя
	// (GET /api/v1/incidents)
	ListIncidents(ctx context.Context, request ListIncidentsRequestObject) (ListIncidentsResponseObject, error)
	// CreateIncident Создать заявку (с дедупом — может приклеить к существующей)
	// (POST /api/v1/incidents)
	CreateIncident(ctx context.Context, request CreateIncidentRequestObject) (CreateIncidentResponseObject, error)
	// RespondHandshake Ответ на «Проблема решена?» из мини-аппа
	// (POST /api/v1/incidents/{id}/handshake-response)
	RespondHandshake(ctx context.Context, request RespondHandshakeRequestObject) (RespondHandshakeResponseObject, error)
	// SubscribeIncident «У меня тоже» (повтор — 204 без изменений)
	// (POST /api/v1/incidents/{id}/subscribe)
	SubscribeIncident(ctx context.Context, request SubscribeIncidentRequestObject) (SubscribeIncidentResponseObject, error)
	// GetProfile Текущий пользователь (создаётся при первом вызове)
	// (GET /api/v1/profile)
	GetProfile(ctx context.Context, request GetProfileRequestObject) (GetProfileResponseObject, error)
	// BindHouse Привязать дом к пользователю
	// (POST /api/v1/profile)
	BindHouse(ctx context.Context, request BindHouseRequestObject) (BindHouseResponseObject, error)

	// (GET /health)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

